// write via role
const writeRoot = page.frameLocator("iframe#settings-frame").frameLocator("iframe#card-frame").getByRole("form", { name: "Nested billing details" })
const writeTarget = writeRoot.getByRole("textbox", { name: "Card number" })
await expect(writeTarget).toBeVisible()
await expect(writeTarget).toBeEditable()
await expect(writeTarget).toHaveValue("5555444433331111")
await writeTarget.fill(INPUT_TEXT)

// submit via role
const submitRoot = page.frameLocator("iframe#settings-frame").frameLocator("iframe#card-frame").getByRole("form", { name: "Nested billing details" })
const submitTarget = submitRoot.getByRole("button", { name: "Save nested card" })
await expect(submitTarget).toBeVisible()
await expect(submitTarget).toBeEnabled()
await submitTarget.click()

// read via css
const readRoot = page.frameLocator("iframe#settings-frame").frameLocator("iframe#card-frame")
const readTarget = readRoot.locator("[data-glasstty-role=\"latest-output\"]")
await expect(readTarget).toBeVisible()
await expect(readTarget).toContainText("Nested saved 1111")
const readText = await readTarget.innerText()
